#include <semaphore>
#include <chrono>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::counting_semaphore<2> semaphore{1};
    assert(decltype(semaphore)::max() >= 2);
    assert(semaphore.try_acquire());
    assert(!semaphore.try_acquire());
    semaphore.release();
    assert(semaphore.try_acquire_for(std::chrono::milliseconds(10)));
    semaphore.release();
    assert(semaphore.try_acquire_until(
        std::chrono::steady_clock::now() + std::chrono::seconds(1)));
}
